import Image from 'next/image';
import { PlaceHolderImages } from '@/lib/placeholder-images';
import { services } from '@/lib/data';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import Link from 'next/link';
import { ArrowRight } from 'lucide-react';
import BackToPreviousButton from '@/components/back-to-previous-button';

const ServiceCard = ({ service }: { service: (typeof services)[0] }) => {
  const cardContent = (
    <Card className="flex h-full flex-col transition-shadow duration-300 hover:shadow-lg">
      <CardHeader>
        <div className="flex items-center gap-4">
          <div className="flex h-12 w-12 items-center justify-center rounded-lg bg-accent/20 text-accent">
            <service.Icon className="h-6 w-6" />
          </div>
          <CardTitle className="text-xl">{service.title}</CardTitle>
        </div>
      </CardHeader>
      <CardContent className="flex flex-1 flex-col">
        <p className="flex-1 text-muted-foreground">{service.description}</p>
        {service.href && (
          <p className="mt-4">
            <span             
              className="font-semibold text-primary hover:underline"
            >
              View Features <ArrowRight className="inline h-4 w-4" />
            </span>
          </p>
        )}
      </CardContent>
    </Card>
  );

  if (service.href) {
    return <Link href={service.href}>{cardContent}</Link>;
  }

  return cardContent;
};

export default function ServicesPage() {
  const servicesHeroImage = PlaceHolderImages.find(
    (img) => img.id === 'services-hero'
  );

  return (
    <div>
      {/* Hero Section */}
      <section className="relative h-[40vh] min-h-[300px] w-full bg-primary text-primary-foreground">
        {servicesHeroImage && (
          <Image
            src={servicesHeroImage.imageUrl}
            alt={servicesHeroImage.description}
            fill
            className="object-cover"
            data-ai-hint={servicesHeroImage.imageHint}
          />
        )}
        <div className="absolute inset-0 bg-primary/70" />
        <div className="relative z-10 flex h-full flex-col items-center justify-center text-center">
          <h1 className="font-headline text-4xl font-extrabold tracking-tight md:text-6xl">
            Products &amp; Services
          </h1>
          <p className="mt-4 max-w-2xl text-lg md:text-xl">
            A complete financial toolkit to build, run, and scale your business.
          </p>
        </div>
      </section>

      {/* Services Grid */}
      <section className="py-16 md:py-24">
        <div className="container mx-auto px-4">
        <BackToPreviousButton />
          <div className="mt-8 grid gap-8 md:grid-cols-2 lg:grid-cols-3">
            {services.map((service) => (
              <ServiceCard key={service.title} service={service} />
            ))}
          </div>
        </div>
      </section>
      
      {/* CTA Section */}
      <section className="bg-secondary py-16 md:py-24">
        <div className="container mx-auto px-4 text-center">
          <h2 className="font-headline text-3xl font-bold md:text-4xl">
            Ready to integrate?
          </h2>
          <p className="mx-auto mt-4 max-w-xl text-lg text-muted-foreground">
            Explore our developer documentation to get started with ZuriPay's powerful APIs.
          </p>
          <Button asChild size="lg" className="mt-8">
            <Link href="/developers">
              Go to Docs <ArrowRight className="ml-2" />
            </Link>
          </Button>
        </div>
      </section>
    </div>
  );
}
